<?php $eyebrow=get_field('eyebrow');$title=get_field('title');$description=get_field('description');$venue=get_field('venue');$address=get_field('address');$email=get_field('email');$phone=get_field('phone');$map_url=get_field('map_url');$button=get_field('button'); ?><section class="sariyah-contact"><div class="sariyah-container"><div class="sariyah-contact__grid"><div><?php if($eyebrow): ?><p class="sariyah-section-eyebrow"><?php echo esc_html($eyebrow); ?></p><?php endif; ?><?php if($title): ?><h2><?php echo esc_html($title); ?></h2><?php endif; ?><?php if($description): ?><p class="sariyah-contact__description"><?php echo esc_html($description); ?></p><?php endif; ?><dl class="sariyah-contact__details"><?php if($venue): ?><div><dt>Event venue</dt><dd><?php echo esc_html($venue); ?></dd></div><?php endif; ?><?php if($address): ?><div><dt>Location address</dt><dd><?php echo esc_html($address); ?></dd></div><?php endif; ?><?php if($email): ?><div><dt>Email</dt><dd><a href="mailto:<?php echo antispambot(sanitize_email($email)); ?>"><?php echo esc_html(antispambot($email)); ?></a></dd></div><?php endif; ?><?php if($phone): ?><div><dt>Phone</dt><dd><a href="tel:<?php echo esc_attr(preg_replace('/[^0-9+]/','',$phone)); ?>"><?php echo esc_html($phone); ?></a></dd></div><?php endif; ?></dl><?php if(is_array($button)&&!empty($button['url'])): ?><a class="sariyah-button" href="<?php echo esc_url($button['url']); ?>"<?php echo !empty($button['target'])?' target="'.esc_attr($button['target']).'" rel="noopener"':''; ?>><?php echo esc_html($button['title']??'Get direction'); ?></a><?php endif; ?></div><div class="sariyah-contact__map"><?php if($map_url): ?><iframe src="<?php echo esc_url($map_url); ?>" loading="lazy" referrerpolicy="no-referrer-when-downgrade" title="Event location map"></iframe><?php else: ?><div class="sariyah-contact__map-placeholder">Add a Google Maps embed URL in the block settings.</div><?php endif; ?></div></div></div></section>